/**
 * Shot catalogue for the marketing screenshots regenerated by every Pages
 * deploy (#648 FR4 / AC3). One row per PNG under `docs/`; adding a new
 * marketing shot is a data edit here, not a spec or workflow change.
 *
 * The renderer in `playwright/tests/visual/marketing-screenshots.spec.ts`
 * iterates this list on the GPU runner, drives `/row` via the demo path, pins
 * tier + lighting + camera-view per entry, settles the scene, and writes the
 * PNG to the output directory the workflow passes in.
 */

export type MarketingTier = 'medium' | 'high' | 'extra-high';
export type MarketingLighting = 'dawn' | 'midday' | 'golden' | 'overcast' | 'dusk';
export type MarketingCameraView = 'chase' | 'side' | 'bow' | 'high';

export interface MarketingShot {
  /** Output filename under `docs/`. Must match the `<img>` src in docs/index.html. */
  readonly file: string;
  /** Human label used in the per-shot report entry (#648 FR9). */
  readonly label: string;
  /** Engine performance tier (`__VIRTUALROW_PERFORMANCE_MODE`). */
  readonly tier: MarketingTier;
  /** Lighting preset (`virtualrow:conditions` in localStorage). */
  readonly lighting: MarketingLighting;
  /** Camera view (`virtualrow:camera-view` in localStorage). */
  readonly view: MarketingCameraView;
  /** Capture viewport in CSS pixels. */
  readonly viewport: { width: number; height: number };
  /**
   * Milliseconds of ride to let elapse before the shutter. GLBs, textures and
   * post-FX settle over several seconds; the activity HUD needs a few PM5
   * frames before the tiles stop reading zero. Default 8s matches the ex-React
   * `SETTLE_MS` that produced the old published shots.
   */
  readonly settleMs: number;
  /**
   * Overlays to hide for a clean scene shot. Each entry is a CSS selector
   * matched inside the ride view; missing selectors are a no-op.
   */
  readonly hiddenOverlays: readonly string[];
}

/**
 * The gallery panels the hero hides so the scene is centre-stage. Mirrors the
 * React-era `HERO_HIDDEN_OVERLAYS`; selectors stay the same across the
 * cutover (the SvelteKit port kept the class names).
 */
export const HERO_HIDDEN_OVERLAYS = [
  '.row-hud-strip',
  '.row-hud-actions',
  '.ghost-picker',
  '.route-info-overlay',
] as const;

/**
 * The activity shot keeps the HUD visible — the whole point of that picture
 * is the live stat tiles — but still hides the picker and start/finish
 * callouts so the frame is deterministic.
 */
export const ACTIVITY_HIDDEN_OVERLAYS = [
  '.ghost-picker',
  '.race-callout',
] as const;

/**
 * The route-selection shot is of the home screen's selected route, so the
 * only chrome in the way is any transient toast.
 */
export const ROUTE_SELECTION_HIDDEN_OVERLAYS = [] as const;

