/** Perceptual-reproducibility tolerance for the self-check (#648 D4 = b, AC2). */
export const MARKETING_COMPARISON = {
  maxDiffPixelRatio: 0.01,
  threshold: 0.3,
  animations: 'disabled' as const,
};

/** Per-shot telemetry recorded alongside each PNG (#648 FR9 / AC8). */
export interface MarketingShotReport {
  readonly file: string;
  readonly label: string;
  readonly tier: MarketingTier;
  readonly lighting: MarketingLighting;
  readonly view: MarketingCameraView;
  readonly viewport: { width: number; height: number };
  readonly outcome: 'ready' | 'fallback' | 'error';
  readonly bytes: number;
  readonly nonZeroPixelRatio: number;
  readonly gpuMs?: number;
  readonly drawCalls?: number;
  readonly sceneryDraws?: number;
  readonly fallbackReason?: string;
  readonly error?: string;
  /** The engine's own `__VIRTUALROW_WEBGPU_HEALTH.adapter` string (vendor / arch / device). */
  readonly adapter?: string;
  /** The engine's own `__VIRTUALROW_WEBGPU_HEALTH.isSoftware`. */
  readonly isSoftware?: boolean;
  /** Raw `navigator.gpu.requestAdapter().info` the page sees, independent of the engine's heuristic. */
  readonly rawAdapter?: {
    readonly vendor?: string;
    readonly architecture?: string;
    readonly device?: string;
    readonly description?: string;
    readonly isFallbackAdapter?: boolean;
  };
  /** The canvas's actual dimensions when readback failed, for the blank-frame debug. */
  readonly canvasSize?: { readonly w: number; readonly h: number };
  /** How many sampled pixels came back non-blank, out of total — null on fallback/error-before-readback. */
  readonly readback?: { readonly nonBlank: number; readonly total: number };
  /** Captured `page.on('console')` lines (error/warning only), truncated. */
  readonly consoleLines?: readonly string[];
  /** Captured `page.on('pageerror')` entries, truncated. */
  readonly pageErrors?: readonly string[];
  /** Non-zero pixel ratio measured on the canvas region only (vs the full-page nzr above). */
  readonly canvasRegionNzr?: number;
}
